function validate([tiles]) {
  if (typeof tiles !== 'string' || tiles.length < 1 || tiles.length > 7) return 'tiles needs 1 to 7 letters.';
  if (!/^[A-Z]+$/.test(tiles)) return 'tiles may contain only uppercase English letters.';
  return null;
}

