function numTilePossibilities(tiles) {
  const count = new Array(26).fill(0);
  for (const tile of tiles) {
    count[tile.charCodeAt(0) - 65]++;
  }

  function extend() {
    let total = 0;
    for (let letter = 0; letter < 26; letter++) {
      if (count[letter] === 0) continue;
      count[letter]--;
      total += 1 + extend();
      count[letter]++;
    }
    return total;
  }

  return extend();
}

