function numTilePossibilities(tiles) {
  const words = new Set();
  const used = new Array(tiles.length).fill(false);
  const grow = (word) => {
    for (let i = 0; i < tiles.length; i++) {
      if (used[i]) continue;
      used[i] = true;
      words.add(word + tiles[i]);
      grow(word + tiles[i]);
      used[i] = false;
    }
  };
  grow('');
  return words.size;
}

