function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'small' ? int(1, 5) : 7;
  const kinds = size === 'small' ? int(1, 4) : int(1, 7);
  const offset = int(0, 26 - kinds);
  let tiles = '';
  for (let i = 0; i < n; i++) tiles += String.fromCharCode(65 + offset + int(0, kinds - 1));
  return [tiles];
}
